body.script:
 //Replace the absolute url part https://obo.de/ with relative syntax: /
 var oboReplaceHotspotImageSrc = function(el)
 {
    var src = jQuery(el).attr('src');
    var newSrc = src.replace('https://obo.de', '');
    jQuery(el).attr('src', newSrc);
 };

 document.addEventListener('readystatechange', function(event) {
    if (document.readyState === "complete") {

        //Replace image src for background image
        let imgs = jQuery('.obo-hotspot-image img');
        imgs.each(function(index) {
          oboReplaceHotspotImageSrc(this);
        });
        
        //Replace image src for hotspot overlay images
        $('.obo-hotspot-marker').on('click', function(e) {
          setTimeout(function() {
            var imgs = jQuery('.hotspot-overlay img');
            imgs.each(function(index) {
              oboReplaceHotspotImageSrc(this);
            });
           }, 500);
        });
    }
  });
